static bool api_index_from_action_case(pthreadpool_fuzzer::Action::ActionCase action_case, size_t* out_idx) {
    if (!out_idx) return false;
    switch (action_case) {
        case pthreadpool_fuzzer::Action::kPthreadpoolCompute1D: *out_idx = 0; return true;
        case pthreadpool_fuzzer::Action::kPthreadpoolCompute1DTiled: *out_idx = 1; return true;
        case pthreadpool_fuzzer::Action::kPthreadpoolCompute2D: *out_idx = 2; return true;
        case pthreadpool_fuzzer::Action::kPthreadpoolCompute2DTiled: *out_idx = 3; return true;
        case pthreadpool_fuzzer::Action::kPthreadpoolCompute3DTiled: *out_idx = 4; return true;
        case pthreadpool_fuzzer::Action::kPthreadpoolCompute4DTiled: *out_idx = 5; return true;
        case pthreadpool_fuzzer::Action::kPthreadpoolCreate: *out_idx = 6; return true;
        case pthreadpool_fuzzer::Action::kPthreadpoolDestroy: *out_idx = 7; return true;
        case pthreadpool_fuzzer::Action::kPthreadpoolGetThreadsCount: *out_idx = 8; return true;
        case pthreadpool_fuzzer::Action::kPthreadpoolParallelize1D: *out_idx = 9; return true;
        case pthreadpool_fuzzer::Action::kPthreadpoolParallelize1DTile1D: *out_idx = 10; return true;
        case pthreadpool_fuzzer::Action::kPthreadpoolParallelize1DWithUarch: *out_idx = 11; return true;
        case pthreadpool_fuzzer::Action::kPthreadpoolParallelize2D: *out_idx = 12; return true;
        case pthreadpool_fuzzer::Action::kPthreadpoolParallelize2DTile1D: *out_idx = 13; return true;
        case pthreadpool_fuzzer::Action::kPthreadpoolParallelize2DTile2D: *out_idx = 14; return true;
        case pthreadpool_fuzzer::Action::kPthreadpoolParallelize2DTile2DWithUarch: *out_idx = 15; return true;
        case pthreadpool_fuzzer::Action::kPthreadpoolParallelize3D: *out_idx = 16; return true;
        case pthreadpool_fuzzer::Action::kPthreadpoolParallelize3DTile1D: *out_idx = 17; return true;
        case pthreadpool_fuzzer::Action::kPthreadpoolParallelize3DTile2D: *out_idx = 18; return true;
        case pthreadpool_fuzzer::Action::kPthreadpoolParallelize3DTile2DWithUarch: *out_idx = 19; return true;
        case pthreadpool_fuzzer::Action::kPthreadpoolParallelize4D: *out_idx = 20; return true;
        case pthreadpool_fuzzer::Action::kPthreadpoolParallelize4DTile1D: *out_idx = 21; return true;
        case pthreadpool_fuzzer::Action::kPthreadpoolParallelize4DTile2D: *out_idx = 22; return true;
        case pthreadpool_fuzzer::Action::kPthreadpoolParallelize4DTile2DWithUarch: *out_idx = 23; return true;
        case pthreadpool_fuzzer::Action::kPthreadpoolParallelize5D: *out_idx = 24; return true;
        case pthreadpool_fuzzer::Action::kPthreadpoolParallelize5DTile1D: *out_idx = 25; return true;
        case pthreadpool_fuzzer::Action::kPthreadpoolParallelize5DTile2D: *out_idx = 26; return true;
        case pthreadpool_fuzzer::Action::kPthreadpoolParallelize6D: *out_idx = 27; return true;
        case pthreadpool_fuzzer::Action::kPthreadpoolParallelize6DTile1D: *out_idx = 28; return true;
        case pthreadpool_fuzzer::Action::kPthreadpoolParallelize6DTile2D: *out_idx = 29; return true;
        default: return false;
    }
}

